import math

def parse_amount(text):
    if not text or not text.strip():
        raise ValueError("Input cannot be empty.")

    # Clean spaces and standardize decimal separator (comma to dot)
    cleaned_text = text.strip()
    processed_text = cleaned_text.replace(',', '.')

    try:
        amount = float(processed_text)
    except ValueError:
        # Catches non-numeric formats, multiple decimal points, etc.
        raise ValueError("Invalid amount format.")

    # Reject negative values
    if amount < 0:
        raise ValueError("Amount cannot be negative.")

    # Reject non-finite values (inf, nan)
    if not math.isfinite(amount):
        raise ValueError("Amount must be a finite number.")

    return amount
